{"command":"mkdir -p /workspace/pkg/formatter /workspace/pkg/config /workspace/pkg/analyze /workspace/pkg/device /workspace/pkg/tui /workspace/cmd

cat << 'EOF' > /workspace/pkg/formatter/formatter.go
package formatter

import (
	"fmt"
)

func FormatSize(bytes int64, useSi bool, useKib bool, raw bool) string {
	if raw {
		return fmt.Sprintf("%10d", bytes)
	}

	if useKib {
		unit := "KiB"
		div := 1024.0
		if useSi {
			unit = "kB"
			div = 1000.0
		}
		val := float64(bytes) / div
		return fmt.Sprintf("%.1f %s", val, unit)
	}

	base := float64(1024)
	units := []string{"B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB"}
	if useSi {
		base = 1000
		units = []string{"B", "kB", "MB", "GB", "TB", "PB", "EB"}
	}

	if bytes == 0 {
		return "0 B"
	}

	val := float64(bytes)
	unitIdx := 0

	for val >= base && unitIdx < len(units)-1 {
		val /= base
		unitIdx++
	}

	if unitIdx == 0 {
		return fmt.Sprintf("%d B", bytes)
	}

	return fmt.Sprintf("%.1f %s", val, units[unitIdx])
}

func AlignSize(sizeStr string, flag rune) string {
	flagStr := " "
	if flag != 0 && flag != ' ' {
		flagStr = string(flag)
	}
	return fmt.Sprintf("%s%10s", flagStr, sizeStr)
}
EOF"}

