func TestFormatSize(t *testing.T) {
	tests := []struct {
		bytes    int64
		useSi    bool
		useKib   bool
		raw      bool
		expected string
	}{
		{0, false, false, false, "0 B"},
		{1, false, false, false, "1 B"},
		{512, false, false, false, "512 B"},
		{999, false, false, false, "999 B"},
