		{1023, false, false, false, "1023 B"},
		{1024, false, false, false, "1.0 KiB"},
		{1500, false, false, false, "1.5 KiB"},
		{1048576, false, false, false, "1.0 MiB"},
		{1073741824, false, false, false, "1.0 GiB"},

		// SI
		{1000, true, false, false, "1.0 kB"},
		{1073741824, true, false, false, "1.1 GB"},

		// KiB
		{1048576, false, true, false, "1024.0 KiB"},
	}

