		res := FormatSize(tt.bytes, tt.useSi, tt.useKib, tt.raw)
		if res != tt.expected {
			t.Errorf("FormatSize(%d, %v, %v, %v) = %q, expected %q", tt.bytes, tt.useSi, tt.useKib, tt.raw, res, tt.expected)
		}
	}
}
