		DirectoryColor string `yaml:"directory-color"`
	} `yaml:"result-row"`
	Header struct {
		TextColor       string `yaml:"text-color"`
		BackgroundColor string `yaml:"background-color"`
		Hidden          bool   `yaml:"hidden"`
	} `yaml:"header"`
	ProgressModal struct {
		CurrentItemPathMaxLen int `yaml:"current-item-path-max-len"`
	} `yaml:"progress-modal"`
	UseOldSizeBar bool `yaml:"use-old-size-bar"`
}

type SortingConfig struct {
	By    string `yaml:"by"`
	Order string `yaml:"order"`
}

type Config struct {
	Style              StyleConfig   `yaml:"style"`
	Sorting            SortingConfig `yaml:"sorting"`
	LogFile            string        `yaml:"log-file"`
	InputFile          string        `yaml:"input-file"`
	OutputFile         string        `yaml:"output-file"`
	IgnoreFromFile     string        `yaml:"ignore-from-file"`
	IgnoreDirs         []string      `yaml:"ignore-dirs"`
	IgnoreDirPatterns  []string      `yaml:"ignore-dir-patterns"`
	Type               []string      `yaml:"type"`
	ExcludeType        []string      `yaml:"exclude-type"`
	MaxCores           int           `yaml:"max-cores"`
	Top                int           `yaml:"top"`
	Depth              int           `yaml:"depth"`
	SequentialScanning bool          `yaml:"sequential-scanning"`
	ShowApparentSize   bool          `yaml:"show-apparent-size"`
	ShowRelativeSize   bool          `yaml:"show-relative-size"`
	ShowAnnexedSize    bool          `yaml:"show-annexed-size"`
	ShowItemCount      bool          `yaml:"show-item-count"`
	ShowMtime          bool          `yaml:"show-mtime"`
	NoColor            bool          `yaml:"no-color"`
	Mouse              bool          `yaml:"mouse"`
	NonInteractive     bool          `yaml:"non-interactive"`
	NoProgress         bool          `yaml:"no-progress"`
	NoUnicode          bool          `yaml:"no-unicode"`
	NoCross            bool          `yaml:"no-cross"`
	NoHidden           bool          `yaml:"no-hidden"`
	NoDelete           bool          `yaml:"no-delete"`
	NoSpawnShell       bool          `yaml:"no-spawn-shell"`
	FollowSymlinks     bool          `yaml:"follow-symlinks"`
	Profiling          bool          `yaml:"profiling"`
	ReadFromStorage    bool          `yaml:"read-from-storage"`
	Db                 string        `yaml:"db"`
	Summarize          bool          `yaml:"summarize"`
	UseSiPrefix        bool          `yaml:"use-si-prefix"`
	NoPrefix           bool          `yaml:"no-prefix"`
	ShowInKib          bool          `yaml:"show-in-kib"`
	ReverseSort        bool          `yaml:"reverse-sort"`
	ChangeCwd          bool          `yaml:"change-cwd"`
	DeleteInBackground bool          `yaml:"delete-in-background"`
	DeleteInParallel   bool          `yaml:"delete-in-parallel"`
	Since              string        `yaml:"since"`
	Until              string        `yaml:"until"`
	MaxAge             string        `yaml:"max-age"`
	MinAge             string        `yaml:"min-age"`
	ArchiveBrowsing    bool          `yaml:"archive-browsing"`
	CollapsePath       bool          `yaml:"collapse-path"`
}

func NewDefaultConfig() *Config {
	cfg := &Config{
		LogFile:           "/dev/null",
		IgnoreDirs:        []string{"/proc", "/dev", "/sys", "/run"},
		IgnoreDirPatterns: []string{},
		Type:              []string{},
		ExcludeType:       []string{},
		MaxCores:          runtime.NumCPU(),
	}
	cfg.Style.Footer.TextColor = "#000000"
	cfg.Style.Footer.BackgroundColor = "#2479D0"
	cfg.Style.Footer.NumberColor = "#FFFFFF"
	cfg.Style.ResultRow.NumberColor = "#e67100"
	cfg.Style.ResultRow.DirectoryColor = "#3498db"
	cfg.Style.Header.TextColor = "#000000"
	cfg.Style.Header.BackgroundColor = "#2479D0"
	return cfg
}

func LoadConfig(configPath string) (*Config, error) {
	cfg := NewDefaultConfig()

	targetPath := configPath
	if targetPath == "" {
		home, err := os.UserHomeDir()
		if err == nil {
			p1 := filepath.Join(home, ".gdu.yaml")
			if _, err := os.Stat(p1); err == nil {
				targetPath = p1
			} else {
				p2 := filepath.Join(home, ".config", "gdu", "gdu.yaml")
				if _, err := os.Stat(p2); err == nil {
					targetPath = p2
				}
			}
		}
	}

	if targetPath == "" {
		return cfg, nil
	}

	data, err := os.ReadFile(targetPath)
	if err != nil {
		if configPath != "" {
			return nil, err
		}
		return cfg, nil
	}

	err = yaml.Unmarshal(data, cfg)
	if err != nil {
		return nil, err
	}

	return cfg, nil
}

func (c *Config) Save(configPath string) error {
	targetPath := configPath
	if targetPath == "" {
		home, err := os.UserHomeDir()
		if err != nil {
			return err
		}
		targetPath = filepath.Join(home, ".gdu.yaml")
	}

	data, err := yaml.Marshal(c)
	if err != nil {
		return err
	}

	return os.WriteFile(targetPath, data, 0644)
}
EOF"}

{"command":"cat << 'EOF' > /workspace/pkg/device/device.go
package device

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/dundee/gdu/v5/pkg/formatter"
	"golang.org/x/sys/unix"
)

type Device struct {
	Name       string
	MountPoint string
	Fstype     string
	Size       int64
	Used       int64
	Free       int64
}

func GetDevices() ([]*Device, error) {
	file, err := os.Open("/proc/mounts")
	if err != nil {
		file, err = os.Open("/etc/mtab")
		if err != nil {
			return nil, err
		}
	}
	defer file.Close()

	var devices []*Device
	seen := make(map[string]bool)

	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		line := scanner.Text()
		parts := strings.Fields(line)
		if len(parts) < 3 {
			continue
		}
		devName := parts[0]
		mountPoint := parts[1]
		fstype := parts[2]

		if !strings.HasPrefix(devName, "/dev/") {
			continue
		}
		if seen[mountPoint] {
			continue
		}
		seen[mountPoint] = true

		var stat unix.Statfs_t
		err := unix.Statfs(mountPoint, &stat)
		if err != nil {
			continue
		}

		size := int64(stat.Blocks) * int64(stat.Bsize)
		free := int64(stat.Bavail) * int64(stat.Bsize)
		used := size - int64(stat.Bfree)*int64(stat.Bsize)
		if used < 0 {
			used = size - free
		}

		devices = append(devices, &Device{
			Name:       devName,
			MountPoint: mountPoint,
			Fstype:     fstype,
			Size:       size,
			Used:       used,
			Free:       free,
		})
	}

	return devices, nil
}

func PrintDevices(devices []*Device, useSi bool, useKib bool) {
	fmt.Printf("%12s %10s %10s %10s %5s %s\n", "Device", "Size", "Used", "Free", "Used%", "Mount point")
	for _, dev := range devices {
		sizeStr := formatter.FormatSize(dev.Size, useSi, useKib, false)
		usedStr := formatter.FormatSize(dev.Used, useSi, useKib, false)
		freeStr := formatter.FormatSize(dev.Free, useSi, useKib, false)
		usedPct := 0
		if dev.Size > 0 {
			usedPct = int(float64(dev.Used) / float64(dev.Size) * 100)
		}
		fmt.Printf("%12s %10s %10s %10s %4d%% %s\n", dev.Name, sizeStr, usedStr, freeStr, usedPct, dev.MountPoint)
	}
}
EOF"}

