{"command":"cat << 'EOF' > /workspace/pkg/analyze/analyze.go
package analyze

import (
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"sync"
	"time"

	"golang.org/x/sys/unix"
)

type Item interface {
	GetName() string
	GetPath() string
	GetSize() int64
	GetApparentSize() int64
	GetItemCount() int
	GetMtime() time.Time
	IsDir() bool
	GetFlag() rune
	GetParent() Item
	SetParent(Item)
	GetFiles() []Item
	SetFiles([]Item)
	AddFile(Item)
	IsReadError() bool
}

type File struct {
	Name         string
	Path         string
	Size         int64
	ApparentSize int64
	Mtime        time.Time
	Flag         rune
	Parent       Item
	Ino          uint64
	IsHardlink   bool
	NotReg       bool
}

func (f *File) GetName() string         { return f.Name }
func (f *File) GetPath() string         { return f.Path }
func (f *File) GetSize() int64         { return f.Size }
func (f *File) GetApparentSize() int64 { return f.ApparentSize }
func (f *File) GetItemCount() int      { return 1 }
func (f *File) GetMtime() time.Time    { return f.Mtime }
func (f *File) IsDir() bool            { return false }
func (f *File) GetFlag() rune          { return f.Flag }
func (f *File) GetParent() Item        { return f.Parent }
func (f *File) SetParent(p Item)       { f.Parent = p }
func (f *File) GetFiles() []Item       { return nil }
func (f *File) SetFiles([]Item)        {}
func (f *File) AddFile(Item)           {}
func (f *File) IsReadError() bool      { return false }

type Dir struct {
	Name         string
	Path         string
	Size         int64
	ApparentSize int64
	ItemCount    int
	Mtime        time.Time
	Flag         rune
	Parent       Item
	Files        []Item
	ReadError    bool
	mu           sync.Mutex
}

func (d *Dir) GetName() string         { return d.Name }
func (d *Dir) GetPath() string         { return d.Path }
func (d *Dir) GetSize() int64         { return d.Size }
func (d *Dir) GetApparentSize() int64 { return d.ApparentSize }
func (d *Dir) GetItemCount() int      { return d.ItemCount }
func (d *Dir) GetMtime() time.Time    { return d.Mtime }
func (d *Dir) IsDir() bool            { return true }
func (d *Dir) GetFlag() rune          { return d.Flag }
func (d *Dir) GetParent() Item        { return d.Parent }
func (d *Dir) SetParent(p Item)       { d.Parent = p }
func (d *Dir) GetFiles() []Item       { return d.Files }
func (d *Dir) SetFiles(f []Item)      { d.Files = f }
func (d *Dir) IsReadError() bool      { return d.ReadError }

func (d *Dir) AddFile(item Item) {
	d.mu.Lock()
	defer d.mu.Unlock()
	d.Files = append(d.Files, item)
	d.Size += item.GetSize()
	d.ApparentSize += item.GetApparentSize()
	d.ItemCount += item.GetItemCount()
	if item.GetMtime().After(d.Mtime) {
		d.Mtime = item.GetMtime()
	}
	if item.GetFlag() == '!' || item.GetFlag() == '.' {
		if d.Flag != '!' {
			d.Flag = '.'
		}
	}
}

type Options struct {
	IgnoreDirs        []string
	IgnoreDirPatterns []*regexp.Regexp
	ExcludeType       []string
	Type              []string
	NoHidden          bool
	NoCross           bool
	FollowSymlinks    bool
	MaxCores          int
	Since             time.Time
	Until             time.Time
	ProgressChan      chan string
}

type Analyzer struct {
	opts      Options
	hardlinks sync.Map
	dev       uint64
	sem       chan struct{}
}

func NewAnalyzer(opts Options) *Analyzer {
	if opts.MaxCores <= 0 {
		opts.MaxCores = 1
	}
	return &Analyzer{
		opts: opts,
		sem:  make(chan struct{}, opts.MaxCores),
	}
}

func (a *Analyzer) Analyze(dirPath string) (Item, error) {
	absPath, err := filepath.Abs(dirPath)
	if err != nil {
		absPath = dirPath
	}

	var stat unix.Stat_t
	err = unix.Lstat(absPath, &stat)
	if err != nil {
		return nil, err
	}

	a.dev = uint64(stat.Dev)

	info, err := os.Stat(absPath)
	if err != nil {
		return nil, err
	}

	if !info.IsDir() {
		return a.processFile(absPath, info.Name(), nil)
	}

	dir := &Dir{
		Name:      info.Name(),
		Path:      absPath,
		ItemCount: 1,
		Mtime:     info.ModTime(),
	}

	a.scanDir(dir)

	if len(dir.Files) == 0 && dir.Flag == 0 {
		dir.Flag = 'e'
	}

	return dir, nil
}

func (a *Analyzer) scanDir(dir *Dir) {
	if a.opts.ProgressChan != nil {
		select {
		case a.opts.ProgressChan <- dir.Path:
		default:
		}
	}

	entries, err := os.ReadDir(dir.Path)
	if err != nil {
		dir.ReadError = true
		dir.Flag = '!'
		return
	}

	var wg sync.WaitGroup

	for _, entry := range entries {
		name := entry.Name()

		if a.opts.NoHidden && strings.HasPrefix(name, ".") {
			continue
		}

		fullPath := filepath.Join(dir.Path, name)

		if a.isIgnored(fullPath, name) {
			continue
		}

		if entry.IsDir() {
			if a.opts.NoCross {
				var stat unix.Stat_t
				if err := unix.Lstat(fullPath, &stat); err == nil {
					if uint64(stat.Dev) != a.dev {
						continue
					}
				}
			}

			subDir := &Dir{
				Name:      name,
				Path:      fullPath,
				ItemCount: 1,
				Parent:    dir,
			}

			if info, err := entry.Info(); err == nil {
				subDir.Mtime = info.ModTime()
			}

			wg.Add(1)
			go func(d *Dir) {
				defer wg.Done()
				a.sem <- struct{}{}
				a.scanDir(d)
				<-a.sem
				dir.AddFile(d)
			}(subDir)

		} else {
			file, err := a.processFile(fullPath, name, dir)
			if err == nil && file != nil {
				dir.AddFile(file)
			}
		}
	}

	wg.Wait()

	if len(dir.Files) == 0 && dir.Flag == 0 {
		dir.Flag = 'e'
	}
}

func (a *Analyzer) processFile(fullPath, name string, parent Item) (Item, error) {
	var stat unix.Stat_t
	var err error

	if a.opts.FollowSymlinks {
		err = unix.Stat(fullPath, &stat)
	} else {
		err = unix.Lstat(fullPath, &stat)
	}

	if err != nil {
		return nil, err
	}

	mtime := time.Unix(stat.Mtim.Sec, stat.Mtim.Nsec)

	if !a.opts.Since.IsZero() && mtime.Before(a.opts.Since) {
		return nil, nil
	}
	if !a.opts.Until.IsZero() && mtime.After(a.opts.Until) {
		return nil, nil
	}

	ext := strings.TrimPrefix(filepath.Ext(name), ".")

	if len(a.opts.Type) > 0 {
		matched := false
		for _, t := range a.opts.Type {
			if strings.EqualFold(ext, t) {
				matched = true
				break
			}
		}
		if !matched {
			return nil, nil
		}
	}

	if len(a.opts.ExcludeType) > 0 {
		for _, t := range a.opts.ExcludeType {
			if strings.EqualFold(ext, t) {
				return nil, nil
			}
		}
	}

	isReg := (stat.Mode & unix.S_IFMT) == unix.S_IFREG
	isSymlink := (stat.Mode & unix.S_IFMT) == unix.S_IFLNK

	dsize := int64(stat.Blocks) * 512
	asize := stat.Size
	var flag rune
	isHardlink := false

	if isReg && stat.Nlink > 1 {
		key := fmt.Sprintf("%d:%d", stat.Dev, stat.Ino)
		if _, loaded := a.hardlinks.LoadOrStore(key, true); loaded {
			dsize = 0
			asize = 0
			flag = 'H'
			isHardlink = true
		} else {
			isHardlink = true
			flag = 'H'
		}
	}

	notReg := false
	if !isReg {
		notReg = true
		flag = '@'
	}
	if isSymlink {
		flag = '@'
	}

	return &File{
		Name:         name,
		Path:         fullPath,
		Size:         dsize,
		ApparentSize: asize,
		Mtime:        mtime,
		Flag:         flag,
		Parent:       parent,
		Ino:          uint64(stat.Ino),
		IsHardlink:   isHardlink,
		NotReg:       notReg,
	}, nil
}

func (a *Analyzer) isIgnored(path, name string) bool {
	for _, ignore := range a.opts.IgnoreDirs {
		if path == ignore || name == ignore || strings.HasPrefix(path, ignore+"/") {
			return true
		}
	}

	for _, re := range a.opts.IgnoreDirPatterns {
		if re.MatchString(path) || re.MatchString(name) {
			return true
		}
	}

	return false
}

func SortItems(items []Item, sortBy string, reverse bool, showApparent bool) {
	sort.Slice(items, func(i, j int) bool {
		var cmp bool
		switch sortBy {
		case "name":
			cmp = items[i].GetName() < items[j].GetName()
		case "itemCount":
			if items[i].GetItemCount() == items[j].GetItemCount() {
				cmp = items[i].GetName() < items[j].GetName()
			} else {
				cmp = items[i].GetItemCount() > items[j].GetItemCount()
			}
		case "mtime":
			if items[i].GetMtime().Equal(items[j].GetMtime()) {
				cmp = items[i].GetName() < items[j].GetName()
			} else {
				cmp = items[i].GetMtime().After(items[j].GetMtime())
			}
		default: // "size"
			var sizeI, sizeJ int64
			if showApparent {
				sizeI, sizeJ = items[i].GetApparentSize(), items[j].GetApparentSize()
			} else {
				sizeI, sizeJ = items[i].GetSize(), items[j].GetSize()
			}
			if sizeI == sizeJ {
				cmp = items[i].GetName() < items[j].GetName()
			} else {
				cmp = sizeI > sizeJ
			}
		}

		if reverse {
			return !cmp
		}
		return cmp
	})
}
EOF"}

