package analyze

import (
	"encoding/json"
	"io"
	"os"
	"path/filepath"
	"time"
)

type ExportHeader struct {
	ProgName  string `json:"progname"`
	ProgVer   string `json:"progver"`
	Timestamp int64  `json:"timestamp"`
}

type DirHeaderJSON struct {
	Name      string `json:"name"`
	Mtime     int64  `json:"mtime"`
	ReadError bool   `json:"read_error,omitempty"`
}

type FileItemJSON struct {
	Name      string `json:"name"`
	Asize     int64  `json:"asize,omitempty"`
	Dsize     int64  `json:"dsize,omitempty"`
	Mtime     int64  `json:"mtime"`
	Ino       uint64 `json:"ino,omitempty"`
	Hlnkc     bool   `json:"hlnkc,omitempty"`
	NotReg    bool   `json:"notreg,omitempty"`
	ReadError bool   `json:"read_error,omitempty"`
}

func ExportToJSON(root Item, version string, w io.Writer) error {
	header := ExportHeader{
		ProgName:  "gdu",
		ProgVer:   version,
		Timestamp: time.Now().Unix(),
	}

	w.Write([]byte("[1,2,"))
	headerData, err := json.Marshal(header)
	if err != nil {
		return err
	}
	w.Write(headerData)
	w.Write([]byte(",\n"))

	err = writeItemJSON(root, w, true)
	if err != nil {
		return err
	}

	w.Write([]byte("]\n"))
	return nil
}

func writeItemJSON(item Item, w io.Writer, isRoot bool) error {
	if item.IsDir() {
		w.Write([]byte("["))
		dirHeader := DirHeaderJSON{
			Name:      item.GetName(),
			Mtime:     item.GetMtime().Unix(),
			ReadError: item.IsReadError(),
		}
		if isRoot {
			dirHeader.Name = item.GetPath()
		}
		data, err := json.Marshal(dirHeader)
		if err != nil {
			return err
		}
		w.Write(data)

		files := item.GetFiles()
		for _, f := range files {
			w.Write([]byte(",\n"))
			err := writeItemJSON(f, w, false)
			if err != nil {
				return err
			}
		}
		w.Write([]byte("]"))
	} else {
		f := item.(*File)
		fileJSON := FileItemJSON{
			Name:   f.Name,
			Asize:  f.ApparentSize,
			Dsize:  f.Size,
			Mtime:  f.Mtime.Unix(),
			Ino:    f.Ino,
			Hlnkc:  f.IsHardlink,
			NotReg: f.NotReg,
		}
		data, err := json.Marshal(fileJSON)
		if err != nil {
			return err
		}
		w.Write(data)
	}
	return nil
}

func ImportFromJSON(filePath string) (Item, error) {
	data, err := os.ReadFile(filePath)
	if err != nil {
		return nil, err
	}

