{"command":"cat << 'EOF' > /workspace/pkg/tui/tui.go
package tui

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/dundee/gdu/v5/pkg/analyze"
	"github.com/dundee/gdu/v5/pkg/config"
	"github.com/dundee/gdu/v5/pkg/formatter"
	"github.com/gdamore/tcell/v2"
	"github.com/mattn/go-runewidth"
)

type UI struct {
	screen           tcell.Screen
	cfg              *config.Config
	root             analyze.Item
	currentDir       analyze.Item
	cursorIndex      int
	scrollOffset     int
	marked           map[string]bool
	showApparentSize bool
	showCount        bool
	showMtime        bool
	sortBy           string
	reverseSort      bool
	filterText       string
	filtering        bool
	activeModal      string // "", "help", "info", "delete", "empty", "export", "file"
	confirmChoice    int    // 0: no, 1: yes, 2: don't ask
	exportFileName   string
	fileLines        []string
	fileScroll       int
	quitPath         string
}

func NewUI(root analyze.Item, cfg *config.Config) (*UI, error) {
	s, err := tcell.NewScreen()
	if err != nil {
		return nil, err
	}

	ui := &UI{
		screen:           s,
		cfg:              cfg,
		root:             root,
		currentDir:       root,
		marked:           make(map[string]bool),
		showApparentSize: cfg.ShowApparentSize,
		showCount:        cfg.ShowItemCount,
		showMtime:        cfg.ShowMtime,
		sortBy:           "size",
		reverseSort:      cfg.ReverseSort,
		exportFileName:   "export.json",
	}

	if cfg.Sorting.By != "" {
		ui.sortBy = cfg.Sorting.By
	}

	return ui, nil
}

func (ui *UI) Run() (string, error) {
	if err := ui.screen.Init(); err != nil {
		return "", err
	}
	defer ui.screen.Fini()

	ui.screen.EnableMouse()

	for {
		ui.draw()
		ui.screen.Show()

		ev := ui.screen.PollEvent()
		switch ev := ev.(type) {
		case *tcell.EventResize:
			ui.screen.Sync()
		case *tcell.EventKey:
			if ui.filtering {
				ui.handleFilterKey(ev)
				continue
			}
			if ui.activeModal != "" {
				if ui.handleModalKey(ev) {
					return ui.quitPath, nil
				}
				continue
			}
			if ui.handleKey(ev) {
				return ui.quitPath, nil
			}
		}
	}
}

func (ui *UI) getVisibleItems() []analyze.Item {
	if ui.currentDir == nil || !ui.currentDir.IsDir() {
		return nil
	}

	rawFiles := ui.currentDir.GetFiles()
	var filtered []analyze.Item

	for _, f := range rawFiles {
		if ui.filterText != "" {
			if !strings.Contains(strings.ToLower(f.GetName()), strings.ToLower(ui.filterText)) {
				continue
			}
		}
		filtered = append(filtered, f)
	}

	analyze.SortItems(filtered, ui.sortBy, ui.reverseSort, ui.showApparentSize)

	var items []analyze.Item
	if ui.currentDir.GetParent() != nil {
		items = append(items, &analyze.Dir{
			Name:   "..",
			Path:   ui.currentDir.GetParent().GetPath(),
			Parent: ui.currentDir.GetParent(),
		})
	}
	items = append(items, filtered...)
	return items
}

func (ui *UI) handleKey(ev *tcell.EventKey) bool {
	items := ui.getVisibleItems()

	switch ev.Key() {
	case tcell.KeyRune:
		switch ev.Rune() {
		case 'q':
			return true
		case 'Q':
			ui.quitPath = ui.currentDir.GetPath()
			return true
		case 'j':
			ui.cursorDown(len(items))
		case 'k':
			ui.cursorUp()
		case 'g':
			ui.cursorIndex = 0
			ui.scrollOffset = 0
		case 'G':
			if len(items) > 0 {
				ui.cursorIndex = len(items) - 1
			}
		case 'l':
			ui.enterSelected(items)
		case 'h':
			ui.goParent()
		case 'a':
			ui.showApparentSize = !ui.showApparentSize
		case 'c':
			ui.showCount = !ui.showCount
		case 'm':
			ui.showMtime = !ui.showMtime
		case 'n':
			ui.sortBy = "name"
		case 's':
			ui.sortBy = "size"
		case 'r':
			// rescan
			analyzer := analyze.NewAnalyzer(analyze.Options{MaxCores: ui.cfg.MaxCores})
			if newRoot, err := analyzer.Analyze(ui.currentDir.GetPath()); err == nil {
				ui.currentDir = newRoot
			}
		case ' ':
			if ui.cursorIndex < len(items) {
				item := items[ui.cursorIndex]
				if item.GetName() != ".." {
					p := item.GetPath()
					ui.marked[p] = !ui.marked[p]
				}
			}
		case 'u':
			ui.marked = make(map[string]bool)
		case 'd':
			if !ui.cfg.NoDelete {
				ui.activeModal = "delete"
				ui.confirmChoice = 0
			}
		case 'e':
			if !ui.cfg.NoDelete {
				ui.activeModal = "empty"
				ui.confirmChoice = 0
			}
		case 'i':
			ui.activeModal = "info"
		case 'v':
			if ui.cursorIndex < len(items) {
				item := items[ui.cursorIndex]
				if !item.IsDir() {
					data, err := os.ReadFile(item.GetPath())
					if err == nil {
						ui.fileLines = strings.Split(string(data), "\n")
						ui.fileScroll = 0
						ui.activeModal = "file"
					}
				}
			}
		case '?':
			ui.activeModal = "help"
		case 'E':
			ui.activeModal = "export"
		case '/':
			ui.filtering = true
		}
	case tcell.KeyDown:
		ui.cursorDown(len(items))
	case tcell.KeyUp:
		ui.cursorUp()
	case tcell.KeyRight, tcell.KeyEnter:
		ui.enterSelected(items)
	case tcell.KeyLeft, tcell.KeyBackspace, tcell.KeyBackspace2:
		ui.goParent()
	case tcell.KeyPgDn:
		_, h := ui.screen.Size()
		ui.cursorIndex += h - 4
		if ui.cursorIndex >= len(items) {
			ui.cursorIndex = len(items) - 1
		}
		if ui.cursorIndex < 0 {
			ui.cursorIndex = 0
		}
	case tcell.KeyPgUp:
		_, h := ui.screen.Size()
		ui.cursorIndex -= h - 4
		if ui.cursorIndex < 0 {
			ui.cursorIndex = 0
		}
	}
	return false
}

func (ui *UI) cursorDown(total int) {
	if total == 0 {
		return
	}
	if ui.cursorIndex < total-1 {
		ui.cursorIndex++
	}
}

func (ui *UI) cursorUp() {
	if ui.cursorIndex > 0 {
		ui.cursorIndex--
	}
}

func (ui *UI) enterSelected(items []analyze.Item) {
	if ui.cursorIndex >= len(items) {
		return
	}
	item := items[ui.cursorIndex]
	if item.GetName() == ".." {
		ui.goParent()
		return
	}
	if item.IsDir() {
		ui.currentDir = item
		ui.cursorIndex = 0
		ui.scrollOffset = 0
	}
}

func (ui *UI) goParent() {
	if ui.currentDir.GetParent() != nil {
		parent := ui.currentDir.GetParent()
		ui.currentDir = parent
		ui.cursorIndex = 0
		ui.scrollOffset = 0
	}
}

func (ui *UI) handleFilterKey(ev *tcell.EventKey) {
	switch ev.Key() {
	case tcell.KeyEscape:
		ui.filtering = false
	case tcell.KeyEnter:
		ui.filtering = false
	case tcell.KeyBackspace, tcell.KeyBackspace2:
		if len(ui.filterText) > 0 {
			ui.filterText = ui.filterText[:len(ui.filterText)-1]
		}
	case tcell.KeyRune:
		ui.filterText += string(ev.Rune())
	}
}

func (ui *UI) handleModalKey(ev *tcell.EventKey) bool {
	switch ui.activeModal {
	case "help", "info":
		if ev.Key() == tcell.KeyEscape || ev.Key() == tcell.KeyRune && (ev.Rune() == 'q' || ev.Rune() == ' ') {
			ui.activeModal = ""
		}
	case "file":
		switch ev.Key() {
		case tcell.KeyEscape:
			ui.activeModal = ""
		case tcell.KeyRune:
			if ev.Rune() == 'q' {
				ui.activeModal = ""
			} else if ev.Rune() == 'j' {
				ui.fileScroll++
			} else if ev.Rune() == 'k' {
				if ui.fileScroll > 0 {
					ui.fileScroll--
				}
			}
		case tcell.KeyDown:
			ui.fileScroll++
		case tcell.KeyUp:
			if ui.fileScroll > 0 {
				ui.fileScroll--
			}
		}
	case "delete", "empty":
		switch ev.Key() {
		case tcell.KeyEscape:
			ui.activeModal = ""
		case tcell.KeyLeft:
			if ui.confirmChoice > 0 {
				ui.confirmChoice--
			}
		case tcell.KeyRight, tcell.KeyTab:
			if ui.confirmChoice < 2 {
				ui.confirmChoice++
			}
		case tcell.KeyEnter:
			if ui.confirmChoice == 1 || ui.confirmChoice == 2 {
				items := ui.getVisibleItems()
				if ui.activeModal == "delete" {
					if len(ui.marked) > 0 {
						for p := range ui.marked {
							os.RemoveAll(p)
						}
						ui.marked = make(map[string]bool)
					} else if ui.cursorIndex < len(items) {
						os.RemoveAll(items[ui.cursorIndex].GetPath())
					}
				} else if ui.activeModal == "empty" {
					if ui.cursorIndex < len(items) {
						dirPath := items[ui.cursorIndex].GetPath()
						entries, _ := os.ReadDir(dirPath)
						for _, entry := range entries {
							os.RemoveAll(filepath.Join(dirPath, entry.Name()))
						}
					}
				}
				// rescan
				analyzer := analyze.NewAnalyzer(analyze.Options{MaxCores: ui.cfg.MaxCores})
				if newRoot, err := analyzer.Analyze(ui.currentDir.GetPath()); err == nil {
					ui.currentDir = newRoot
				}
			}
			ui.activeModal = ""
		}
	case "export":
		switch ev.Key() {
		case tcell.KeyEscape:
			ui.activeModal = ""
		case tcell.KeyEnter:
			f, err := os.Create(ui.exportFileName)
			if err == nil {
				analyze.ExportToJSON(ui.currentDir, "dev", f)
				f.Close()
			}
			ui.activeModal = ""
		}
	}
	return false
}

func (ui *UI) draw() {
	ui.screen.Clear()
	w, h := ui.screen.Size()

	// Header line 0
	headerStyle := tcell.StyleDefault.Background(tcell.Color236).Foreground(tcell.ColorWhite)
	ui.drawString(0, 0, " gdu ~ Use arrow keys to navigate, press ? for help", headerStyle, w)

	// Subheader line 1
	subHeaderStyle := tcell.StyleDefault.Foreground(tcell.ColorWhite)
	dirTitle := fmt.Sprintf(" --- %s ---", ui.currentDir.GetPath())
	ui.drawString(0, 1, dirTitle, subHeaderStyle, w)

	items := ui.getVisibleItems()
	maxSize := int64(1)
	for _, item := range items {
		if item.GetName() == ".." {
			continue
		}
		sz := item.GetSize()
		if ui.showApparentSize {
			sz = item.GetApparentSize()
		}
		if sz > maxSize {
			maxSize = sz
		}
	}

	visibleRows := h - 3
	if ui.cursorIndex < ui.scrollOffset {
		ui.scrollOffset = ui.cursorIndex
	}
	if ui.cursorIndex >= ui.scrollOffset+visibleRows {
		ui.scrollOffset = ui.cursorIndex - visibleRows + 1
	}

	for i := 0; i < visibleRows; i++ {
		idx := ui.scrollOffset + i
		if idx >= len(items) {
			break
		}
		item := items[idx]
		rowY := 2 + i

		style := tcell.StyleDefault
		if idx == ui.cursorIndex {
			style = style.Background(tcell.Color238).Foreground(tcell.ColorWhite)
		}

		if item.GetName() == ".." {
			line := fmt.Sprintf("                         /..")
			ui.drawString(0, rowY, line, style, w)
			continue
		}

		sz := item.GetSize()
		if ui.showApparentSize {
			sz = item.GetApparentSize()
		}

		szStr := formatter.FormatSize(sz, ui.cfg.UseSiPrefix, ui.cfg.ShowInKib, ui.cfg.NoPrefix)
		alignedSz := formatter.AlignSize(szStr, item.GetFlag())

		bar := renderBar(sz, maxSize, ui.cfg.NoUnicode)

		countStr := ""
		if ui.showCount {
			countStr = fmt.Sprintf(" %5d", item.GetItemCount())
		}

		mtimeStr := ""
		if ui.showMtime {
			mtimeStr = fmt.Sprintf("%s ", item.GetMtime().Format("2006-01-02 15:04:05"))
		}

		markStr := "  "
		if len(ui.marked) > 0 {
			if ui.marked[item.GetPath()] {
				markStr = "✓ "
			}
		}

		nameStr := item.GetName()
		if item.IsDir() {
			nameStr = "/" + nameStr
		}

		rowText := fmt.Sprintf("%s %s▏%s%s%s%s", alignedSz, bar, countStr, mtimeStr, markStr, nameStr)
		ui.drawString(0, rowY, rowText, style, w)
	}

	// Footer line
	totalUsage := ui.currentDir.GetSize()
	apparentSize := ui.currentDir.GetApparentSize()
	totalItems := ui.currentDir.GetItemCount()

	footerStyle := tcell.StyleDefault.Background(tcell.Color236).Foreground(tcell.ColorWhite)
	footerText := fmt.Sprintf(" Total disk usage: %s Apparent size: %s Items: %d Sorting by: %s",
		formatter.FormatSize(totalUsage, ui.cfg.UseSiPrefix, ui.cfg.ShowInKib, false),
		formatter.FormatSize(apparentSize, ui.cfg.UseSiPrefix, ui.cfg.ShowInKib, false),
		totalItems,
		ui.sortBy,
	)

	if len(ui.marked) > 0 {
		footerText = fmt.Sprintf(" Selected items: %d%s", len(ui.marked), footerText)
	}

	if ui.filtering {
		footerText = fmt.Sprintf("Filter: [%s] %s", ui.filterText, footerText)
	} else if ui.filterText != "" {
		footerText = fmt.Sprintf("%s %s", ui.filterText, footerText)
	}

	ui.drawString(0, h-1, footerText, footerStyle, w)

	// Render modal if active
	if ui.activeModal != "" {
		ui.drawModal(w, h)
	}
}

func renderBar(size, maxSize int64, noUnicode bool) string {
	if maxSize <= 0 {
		maxSize = 1
	}
	ratio := float64(size) / float64(maxSize)
	if ratio > 1.0 {
		ratio = 1.0
	}

	if noUnicode {
		numHash := int(ratio * 10)
		return fmt.Sprintf("[%s%s]", strings.Repeat("#", numHash), strings.Repeat(" ", 10-numHash))
	}

	blocks := []string{" ", "▏", "▎", "▍", "▌", "▋", "▊", "▉", "█"}
	val := ratio * 10.0
	full := int(val)
	frac := int((val - float64(full)) * 8.0)

	var sb strings.Builder
	for i := 0; i < full; i++ {
		sb.WriteString("█")
	}
	if full < 10 {
		if frac > 0 {
			sb.WriteString(blocks[frac])
		}
		for sb.Len() < 10 {
			sb.WriteString(" ")
		}
	}

	barStr := sb.String()
	runes := []rune(barStr)
	if len(runes) > 10 {
		barStr = string(runes[:10])
	} else if len(runes) < 10 {
		barStr = barStr + strings.Repeat(" ", 10-len(runes))
	}

	return barStr
}

func (ui *UI) drawModal(screenW, screenH int) {
	switch ui.activeModal {
	case "help":
		boxW, boxH := 80, 22
		startX := (screenW - boxW) / 2
		startY := (screenH - boxH) / 2
		ui.drawBox(startX, startY, boxW, boxH, " gdu help ")

		lines := []string{
			"",
			"       up/down, k/j    Move cursor up/down",
			"    pgup/pgdn, g/G     Move cursor top/bottom",
			"   enter, right, l     Go to directory/device",
			"           left, h     Go to parent directory",
			"",
			"                 r     Rescan current directory",
			"                 E     Export analysis data to file as JSON",
			"                 /     Search items by name",
			"                 a     Toggle between showing disk usage and apparent size",
			"                 B     Toggle bar alignment to biggest file or directory",
			"                 c     Show/hide file count",
			"                 m     Show/hide latest mtime",
			"                 b     Spawn shell in current directory",
			"                 q     Quit gdu",
			"                 Q     Quit gdu and print current directory path",
			"",
			"  Item under cursor:",
			"                 d     Delete file or directory",
		}

		for i, l := range lines {
			if startY+1+i < startY+boxH-1 {
				ui.drawString(startX+2, startY+1+i, l, tcell.StyleDefault, boxW-4)
			}
		}

	case "info":
		items := ui.getVisibleItems()
		if ui.cursorIndex >= len(items) {
			return
		}
		item := items[ui.cursorIndex]

		boxW, boxH := 80, 14
		startX := (screenW - boxW) / 2
		startY := (screenH - boxH) / 2
		ui.drawBox(startX, startY, boxW, boxH, " Item info ")

		itemType := "File"
		if item.IsDir() {
			itemType = "Directory"
		}

		lines := []string{
			"",
			fmt.Sprintf("  Name: %s", item.GetName()),
			fmt.Sprintf("  Path: %s", item.GetPath()),
			fmt.Sprintf("  Type: %s", itemType),
			"",
			fmt.Sprintf("     Disk usage: %s (%d B)", formatter.FormatSize(item.GetSize(), false, false, false), item.GetSize()),
			fmt.Sprintf("  Apparent size: %s (%d B)", formatter.FormatSize(item.GetApparentSize(), false, false, false), item.GetApparentSize()),
		}

		for i, l := range lines {
			ui.drawString(startX+2, startY+1+i, l, tcell.StyleDefault, boxW-4)
		}

	case "delete", "empty":
		boxW, boxH := 45, 9
		startX := (screenW - boxW) / 2
		startY := (screenH - boxH) / 2
		ui.drawBox(startX, startY, boxW, boxH, "")

		titleMsg := "Are you sure you want to delete"
		if ui.activeModal == "empty" {
			titleMsg = "Are you sure you want to empty"
		}

		items := ui.getVisibleItems()
		itemName := ""
		if len(ui.marked) > 0 {
			itemName = fmt.Sprintf("%d items?", len(ui.marked))
		} else if ui.cursorIndex < len(items) {
			itemName = fmt.Sprintf("%q?", items[ui.cursorIndex].GetName())
		}

		ui.drawString(startX+4, startY+2, titleMsg, tcell.StyleDefault, boxW-8)
		ui.drawString(startX+4, startY+3, itemName, tcell.StyleDefault, boxW-8)

		opts := []string{"no", "yes", "don't ask me again"}
		optX := startX + 6
		for i, opt := range opts {
			style := tcell.StyleDefault
			if i == ui.confirmChoice {
				style = style.Background(tcell.ColorWhite).Foreground(tcell.ColorBlack)
			}
			ui.drawString(optX, startY+5, opt, style, len(opt))
			optX += len(opt) + 4
		}

	case "export":
		boxW, boxH := 50, 7
		startX := (screenW - boxW) / 2
		startY := (screenH - boxH) / 2
		ui.drawBox(startX, startY, boxW, boxH, " Export data to JSON ")

		ui.drawString(startX+3, startY+2, fmt.Sprintf("File name %s", ui.exportFileName), tcell.StyleDefault, boxW-6)
		ui.drawString(startX+20, startY+4, "Export", tcell.StyleDefault.Background(tcell.ColorWhite).Foreground(tcell.ColorBlack), 6)
	}
}

func (ui *UI) drawBox(x, y, w, h int, title string) {
	style := tcell.StyleDefault

	// Corners and borders
	ui.screen.SetContent(x, y, '╔', nil, style)
	ui.screen.SetContent(x+w-1, y, '╗', nil, style)
	ui.screen.SetContent(x, y+h-1, '╚', nil, style)
	ui.screen.SetContent(x+w-1, y+h-1, '╝', nil, style)

	for i := 1; i < w-1; i++ {
		ui.screen.SetContent(x+i, y, '═', nil, style)
		ui.screen.SetContent(x+i, y+h-1, '═', nil, style)
	}
	for j := 1; j < h-1; j++ {
		ui.screen.SetContent(x, y+j, '║', nil, style)
		ui.screen.SetContent(x+w-1, y+j, '║', nil, style)

		for i := 1; i < w-1; i++ {
			ui.screen.SetContent(x+i, y+j, ' ', nil, style)
		}
	}

	if title != "" {
		ui.drawString(x+(w-len(title))/2, y, title, style, len(title))
	}
}

func (ui *UI) drawString(x, y int, str string, style tcell.Style, maxW int) {
	col := x
	for _, r := range str {
		rw := runewidth.RuneWidth(r)
		if col+rw > x+maxW {
			break
		}
		ui.screen.SetContent(col, y, r, nil, style)
		col += rw
	}
}
