	szStr := formatter.FormatSize(sz, cfg.UseSiPrefix, cfg.ShowInKib, cfg.NoPrefix)
	aligned := formatter.AlignSize(szStr, item.GetFlag())

	nameStr := item.GetPath()
	fmt.Printf("%s %s\n", aligned, nameStr)

	if currentDepth < maxDepth && item.IsDir() {
		files := item.GetFiles()
		analyze.SortItems(files, "size", cfg.ReverseSort, cfg.ShowApparentSize)
		for _, child := range files {
			printTreeDepth(child, currentDepth+1, maxDepth, cfg)
		}
	}
