func runRoot(cmd *cobra.Command, args []string) error {
	if versionFlag {
		fmt.Printf("Version:\t %s\nBuilt time:\t %s\nBuilt user:\t %s\n", Version, BuiltTime, BuiltUser)
		return nil
	}

	cfg, err := config.LoadConfig(configFile)
	if err != nil {
		return err
	}

	applyFlagsToConfig(cmd, cfg)

	if writeConfig {
		err := cfg.Save(configFile)
		if err != nil {
			return err
		}
	}

	if showDisks {
		devices, err := device.GetDevices()
		if err != nil {
			return err
		}
		device.PrintDevices(devices, cfg.UseSiPrefix, cfg.ShowInKib)
		return nil
	}

	targetPath := "."
	if len(args) > 0 {
		targetPath = args[0]
	}

	var root analyze.Item

	if cfg.InputFile != "" {
		imported, err := analyze.ImportFromJSON(cfg.InputFile)
		if err != nil {
			return err
		}
		root = imported
	} else {
		var sinceTime, untilTime time.Time
		if cfg.Since != "" {
			sinceTime, _ = parseTime(cfg.Since)
		}
		if cfg.Until != "" {
			untilTime, _ = parseTime(cfg.Until)
		}

		var rePatterns []*regexp.Regexp
		for _, pat := range cfg.IgnoreDirPatterns {
			re, err := regexp.Compile(pat)
			if err != nil {
				return err
			}
			rePatterns = append(rePatterns, re)
		}

		opts := analyze.Options{
			IgnoreDirs:        cfg.IgnoreDirs,
			IgnoreDirPatterns: rePatterns,
			ExcludeType:       cfg.ExcludeType,
			Type:              cfg.Type,
			NoHidden:          cfg.NoHidden,
			NoCross:           cfg.NoCross,
			FollowSymlinks:    cfg.FollowSymlinks,
			MaxCores:          cfg.MaxCores,
			Since:             sinceTime,
			Until:             untilTime,
		}

		analyzer := analyze.NewAnalyzer(opts)
		analyzed, err := analyzer.Analyze(targetPath)
		if err != nil {
			return err
		}
		root = analyzed
	}

	if cfg.OutputFile != "" {
		f, err := os.Create(cfg.OutputFile)
		if err != nil {
			return err
		}
		defer f.Close()
		err = analyze.ExportToJSON(root, Version, f)
		if err != nil {
			return err
		}
	}

	isTTY := isatty.IsTerminal(os.Stdout.Fd())

	if cfg.NonInteractive || !isTTY {
		runNonInteractive(root, cfg, isTTY)
		return nil
	}

	ui, err := tui.NewUI(root, cfg)
	if err != nil {
		return err
	}

	quitPath, err := ui.Run()
	if err != nil {
		return err
	}

	if quitPath != "" {
		fmt.Println(quitPath)
	}

	return nil
}

func applyFlagsToConfig(cmd *cobra.Command, cfg *config.Config) {
	if cmd.Flags().Changed("show-apparent-size") {
		cfg.ShowApparentSize = showApparentSize
	}
	if cmd.Flags().Changed("no-color") {
