	}
	if cmd.Flags().Changed("reverse-sort") {
		cfg.ReverseSort = reverseSort
	}
	if cmd.Flags().Changed("summarize") {
		cfg.Summarize = summarize
	}
	if cmd.Flags().Changed("top") {
		cfg.Top = top
	}
	if cmd.Flags().Changed("depth") {
		cfg.Depth = depth
	}
	if cmd.Flags().Changed("max-cores") {
		cfg.MaxCores = maxCores
	}
	if cmd.Flags().Changed("input-file") {
		cfg.InputFile = inputFile
	}
	if cmd.Flags().Changed("output-file") {
		cfg.OutputFile = outputFile
	}
	if cmd.Flags().Changed("no-hidden") {
		cfg.NoHidden = noHidden
	}
	if cmd.Flags().Changed("no-cross") {
		cfg.NoCross = noCross
	}
	if cmd.Flags().Changed("follow-symlinks") {
		cfg.FollowSymlinks = followSymlinks
	}
	if cmd.Flags().Changed("ignore-dirs") {
		cfg.IgnoreDirs = ignoreDirs
	}
	if cmd.Flags().Changed("ignore-dirs-pattern") {
		cfg.IgnoreDirPatterns = ignoreDirPatterns
	}
	if cmd.Flags().Changed("type") {
		cfg.Type = incType
	}
	if cmd.Flags().Changed("exclude-type") {
		cfg.ExcludeType = excludeType
	}
	if cmd.Flags().Changed("since") {
		cfg.Since = since
	}
	if cmd.Flags().Changed("until") {
		cfg.Until = until
	}
}

func runNonInteractive(root analyze.Item, cfg *config.Config, isTTY bool) {
	if cfg.Summarize {
		sz := root.GetSize()
		if cfg.ShowApparentSize {
			sz = root.GetApparentSize()
		}
		fmt.Printf("%s %s\n", formatter.AlignSize(formatter.FormatSize(sz, cfg.UseSiPrefix, cfg.ShowInKib, cfg.NoPrefix), 0), root.GetName())
		return
	}

	if cfg.Depth > 0 {
		printTreeDepth(root, 1, cfg.Depth, cfg)
		return
	}

	if !root.IsDir() {
		return
	}

	files := root.GetFiles()
	analyze.SortItems(files, "size", cfg.ReverseSort, cfg.ShowApparentSize)

	if cfg.Top > 0 && len(files) > cfg.Top {
		files = files[:cfg.Top]
	}

	for _, item := range files {
		sz := item.GetSize()
		if cfg.ShowApparentSize {
			sz = item.GetApparentSize()
		}
		szStr := formatter.FormatSize(sz, cfg.UseSiPrefix, cfg.ShowInKib, cfg.NoPrefix)
		aligned := formatter.AlignSize(szStr, item.GetFlag())

		nameStr := item.GetName()
		if item.IsDir() {
			nameStr = "/" + nameStr
		}

		useColor := isTTY && !cfg.NoColor
		if useColor {
			if item.IsDir() {
				fmt.Printf("%s \x1b[34;1m%s\x1b[0;22m\n", aligned, nameStr)
			} else {
				fmt.Printf("%s %s\n", aligned, nameStr)
			}
		} else {
			fmt.Printf("%s %s\n", aligned, nameStr)
		}
	}
}

func printTreeDepth(item analyze.Item, currentDepth, maxDepth int, cfg *config.Config) {
	sz := item.GetSize()
	if cfg.ShowApparentSize {
		sz = item.GetApparentSize()
	}
	szStr := formatter.FormatSize(sz, cfg.UseSiPrefix, cfg.ShowInKib, cfg.NoPrefix)
	aligned := formatter.AlignSize(szStr, item.GetFlag())

	nameStr := item.GetPath()
	fmt.Printf("%s %s\n", aligned, nameStr)

	if currentDepth < maxDepth && item.IsDir() {
		files := item.GetFiles()
		analyze.SortItems(files, "size", cfg.ReverseSort, cfg.ShowApparentSize)
		for _, child := range files {
			printTreeDepth(child, currentDepth+1, maxDepth, cfg)
		}
	}
}

