func Execute() {
	if err := rootCmd.Execute(); err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}
}

func runRoot(cmd *cobra.Command, args []string) error {
	if versionFlag {
		fmt.Printf("Version:\t %s\nBuilt time:\t %s\nBuilt user:\t %s\n", Version, BuiltTime, BuiltUser)
		return nil
	}

	cfg, err := config.LoadConfig(configFile)
	if err != nil {
		return err
	}

	applyFlagsToConfig(cmd, cfg)

	if writeConfig {
		err := cfg.Save(configFile)
		if err != nil {
			return err
		}
	}

	if showDisks {
		devices, err := device.GetDevices()
		if err != nil {
			return err
		}
		device.PrintDevices(devices, cfg.UseSiPrefix, cfg.ShowInKib)
		return nil
	}

	targetPath := "."
	if len(args) > 0 {
		targetPath = args[0]
	}

	var root analyze.Item

	if cfg.InputFile != "" {
		imported, err := analyze.ImportFromJSON(cfg.InputFile)
		if err != nil {
			return err
		}
		root = imported
	} else {
		var sinceTime, untilTime time.Time
		if cfg.Since != "" {
			sinceTime, _ = parseTime(cfg.Since)
		}
		if cfg.Until != "" {
			untilTime, _ = parseTime(cfg.Until)
		}

		var rePatterns []*regexp.Regexp
		for _, pat := range cfg.IgnoreDirPatterns {
			re, err := regexp.Compile(pat)
			if err != nil {
				return err
			}
			rePatterns = append(rePatterns, re)
		}

		opts := analyze.Options{
			IgnoreDirs:        cfg.IgnoreDirs,
			IgnoreDirPatterns: rePatterns,
			ExcludeType:       cfg.ExcludeType,
			Type:              cfg.Type,
			NoHidden:          cfg.NoHidden,
			NoCross:           cfg.NoCross,
			FollowSymlinks:    cfg.FollowSymlinks,
			MaxCores:          cfg.MaxCores,
			Since:             sinceTime,
			Until:             untilTime,
		}

		analyzer := analyze.NewAnalyzer(opts)
		analyzed, err := analyzer.Analyze(targetPath)
		if err != nil {
			return err
		}
		root = analyzed
	}

	if cfg.OutputFile != "" {
		f, err := os.Create(cfg.OutputFile)
		if err != nil {
			return err
		}
		defer f.Close()
		err = analyze.ExportToJSON(root, Version, f)
		if err != nil {
			return err
		}
	}

	isTTY := isatty.IsTerminal(os.Stdout.Fd())

	if cfg.NonInteractive || !isTTY {
		runNonInteractive(root, cfg, isTTY)
		return nil
	}

	ui, err := tui.NewUI(root, cfg)
	if err != nil {
		return err
	}

	quitPath, err := ui.Run()
	if err != nil {
		return err
	}

	if quitPath != "" {
		fmt.Println(quitPath)
	}

	return nil
}

func applyFlagsToConfig(cmd *cobra.Command, cfg *config.Config) {
	if cmd.Flags().Changed("show-apparent-size") {
		cfg.ShowApparentSize = showApparentSize
	}
	if cmd.Flags().Changed("no-color") {
		cfg.NoColor = noColor
	}
	if cmd.Flags().Changed("show-item-count") {
		cfg.ShowItemCount = showItemCount
	}
	if cmd.Flags().Changed("show-mtime") {
		cfg.ShowMtime = showMtime
	}
	if cmd.Flags().Changed("non-interactive") {
		cfg.NonInteractive = nonInteractive
	}
	if cmd.Flags().Changed("no-progress") {
		cfg.NoProgress = noProgress
	}
	if cmd.Flags().Changed("show-in-kib") {
		cfg.ShowInKib = showInKib
	}
	if cmd.Flags().Changed("si") {
		cfg.UseSiPrefix = si
	}
	if cmd.Flags().Changed("no-prefix") {
		cfg.NoPrefix = noPrefix
	}
	if cmd.Flags().Changed("reverse-sort") {
		cfg.ReverseSort = reverseSort
	}
	if cmd.Flags().Changed("summarize") {
		cfg.Summarize = summarize
	}
	if cmd.Flags().Changed("top") {
		cfg.Top = top
	}
	if cmd.Flags().Changed("depth") {
		cfg.Depth = depth
	}
	if cmd.Flags().Changed("max-cores") {
		cfg.MaxCores = maxCores
	}
	if cmd.Flags().Changed("input-file") {
		cfg.InputFile = inputFile
	}
	if cmd.Flags().Changed("output-file") {
		cfg.OutputFile = outputFile
	}
	if cmd.Flags().Changed("no-hidden") {
		cfg.NoHidden = noHidden
	}
	if cmd.Flags().Changed("no-cross") {
		cfg.NoCross = noCross
	}
	if cmd.Flags().Changed("follow-symlinks") {
		cfg.FollowSymlinks = followSymlinks
	}
	if cmd.Flags().Changed("ignore-dirs") {
		cfg.IgnoreDirs = ignoreDirs
	}
	if cmd.Flags().Changed("ignore-dirs-pattern") {
		cfg.IgnoreDirPatterns = ignoreDirPatterns
	}
	if cmd.Flags().Changed("type") {
		cfg.Type = incType
	}
	if cmd.Flags().Changed("exclude-type") {
		cfg.ExcludeType = excludeType
	}
	if cmd.Flags().Changed("since") {
		cfg.Since = since
	}
	if cmd.Flags().Changed("until") {
		cfg.Until = until
	}
}

func runNonInteractive(root analyze.Item, cfg *config.Config, isTTY bool) {
	if cfg.Summarize {
		sz := root.GetSize()
		if cfg.ShowApparentSize {
			sz = root.GetApparentSize()
		}
		fmt.Printf("%s %s\n", formatter.AlignSize(formatter.FormatSize(sz, cfg.UseSiPrefix, cfg.ShowInKib, cfg.NoPrefix), 0), root.GetName())
		return
	}

	if cfg.Depth > 0 {
		printTreeDepth(root, 1, cfg.Depth, cfg)
		return
	}

	if !root.IsDir() {
		return
	}

	files := root.GetFiles()
	analyze.SortItems(files, "size", cfg.ReverseSort, cfg.ShowApparentSize)

	if cfg.Top > 0 && len(files) > cfg.Top {
		files = files[:cfg.Top]
	}

	for _, item := range files {
		sz := item.GetSize()
		if cfg.ShowApparentSize {
			sz = item.GetApparentSize()
		}
		szStr := formatter.FormatSize(sz, cfg.UseSiPrefix, cfg.ShowInKib, cfg.NoPrefix)
		aligned := formatter.AlignSize(szStr, item.GetFlag())

		nameStr := item.GetName()
		if item.IsDir() {
			nameStr = "/" + nameStr
		}

		useColor := isTTY && !cfg.NoColor
		if useColor {
			if item.IsDir() {
				fmt.Printf("%s \x1b[34;1m%s\x1b[0;22m\n", aligned, nameStr)
			} else {
				fmt.Printf("%s %s\n", aligned, nameStr)
			}
		} else {
			fmt.Printf("%s %s\n", aligned, nameStr)
		}
	}
}

func printTreeDepth(item analyze.Item, currentDepth, maxDepth int, cfg *config.Config) {
	sz := item.GetSize()
	if cfg.ShowApparentSize {
		sz = item.GetApparentSize()
	}
	szStr := formatter.FormatSize(sz, cfg.UseSiPrefix, cfg.ShowInKib, cfg.NoPrefix)
	aligned := formatter.AlignSize(szStr, item.GetFlag())

	nameStr := item.GetPath()
	fmt.Printf("%s %s\n", aligned, nameStr)

	if currentDepth < maxDepth && item.IsDir() {
		files := item.GetFiles()
		analyze.SortItems(files, "size", cfg.ReverseSort, cfg.ShowApparentSize)
		for _, child := range files {
			printTreeDepth(child, currentDepth+1, maxDepth, cfg)
		}
	}
}

func parseTime(str string) (time.Time, error) {
	if t, err := time.Parse(time.RFC3339, str); err == nil {
		return t, nil
	}
	if t, err := time.Parse("2006-01-02", str); err == nil {
		return t, nil
	}
	return time.Time{}, fmt.Errorf("invalid time format: %s", str)
}
